(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.35)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.38)*12 + Math.cos((x-y)*0.009-t*0.18)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9, 0.9],
    [80+Math.sin(t*0.7+3)*110, 40+Math.cos(t*0.6+4)*60, 0.085, 2.1, 0.85],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.8+1)*80, 0.075, 1.8, 1.05],
    [200+Math.sin(t*0.55+6)*90, 220+Math.cos(t*0.75+3)*50, 0.095, 2.4, 0.75]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const a = Math.sin(d*f-t*sp)*w;
    const b = Math.cos(d*f*0.73+t*sp*0.55+1.2)*w*0.6;
    const c = Math.sin(d*f*0.4+t*sp*0.3+3.0)*w*0.35;
    aS += a; iS += b; cS += c;
  }
  aS/=9; iS/=9; cS/=9;
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9) + Math.sin(sx*0.028-sy*0.038+t*1.3) + Math.sin(sx*0.05+sy*0.015-t*0.7))/3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.6);
  const sp2 = Math.sin(dist*0.035+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const turb = Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.2)*Math.sin((sx-sy)*0.05+t*0.8);
  const reaction = Math.tanh((aS - iS*0.65 + bg*0.25 + spiral*0.4 + cS*0.2 + turb*0.15)*2.0);
  const react2 = Math.tanh((aS*0.8 + iS*0.5 - cS*0.3 + spiral*0.3 - turb*0.2)*1.6);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13) + Math.sin((sx+sy)*0.09+t*0.7)*0.6 + Math.sin(sx*0.07-t*0.5)*Math.cos(sy*0.11+t*0.4)*0.3)*1.4)*0.35;
  const micro = Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08*Math.abs(reaction);
  const blend = reaction*0.5 + react2*0.2 + cell*0.2 + micro;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[15,90,120],[20,140,145],[45,175,140],
    [120,195,100],[190,200,70],[220,175,55],[215,130,60],[200,85,55],
    [170,50,60],[120,30,55],[70,18,48],[30,12,42],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.3?1.05:0.92;
  const glow = Math.max(0, 1-dist*0.003)*0.15+0.85;
  const finalL = lum*edge*glow;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*finalL)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*finalL)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*finalL)|0
  ];
}
